{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Although the bucket currently uses a private ACL, no account-independent bucket-level controls prevent future public ACLs or public bucket policies."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The financials bucket does not record server access requests, limiting detection and investigation of unauthorized or suspicious access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 versioning is disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Without versioning, financial objects overwritten or deleted accidentally or maliciously cannot be recovered from prior versions."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket lacks KMS default encryption",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The bucket has no explicit KMS-backed default encryption configuration, reducing control and auditability over encryption of financial data."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive deletion of bucket contents is enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete all financial object versions when destroying the bucket, increasing the impact of an erroneous or compromised deployment."
    }
  ],
  "patched_code": "data "aws_caller_identity" "current" {}

resource "aws_kms_key" "financials" {
  description             = "KMS key for the financials S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "financials" {
  bucket = aws_s3_bucket.financials.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "financials" {
  bucket = aws_s3_bucket.financials.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "financials" {
  bucket = aws_s3_bucket.financials.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.financials.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "financials_logs" {
  bucket        = "${local.resource_prefix.value}-financials-logs"
  force_destroy = false

  tags = merge({
    Name        = "${local.resource_prefix.value}-financials-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "financials_logs" {
  bucket = aws_s3_bucket.financials_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "financials_logs" {
  bucket = aws_s3_bucket.financials_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "financials_logs" {
  bucket = aws_s3_bucket.financials_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "financials_logs" {
  bucket = aws_s3_bucket.financials_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsPolicy"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.financials_logs.arn}/financials/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.financials.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "financials" {
  bucket        = aws_s3_bucket.financials.id
  target_bucket = aws_s3_bucket.financials_logs.id
  target_prefix = "financials/"

  depends_on = [aws_s3_bucket_policy.financials_logs]
}
",
  "fix_summary": "Added public-access blocking, versioning, KMS encryption, and server access logging to a secured log bucket. Disabled destructive forced deletion for the financials bucket and enabled KMS key rotation."
}
